/**
 * ATLAS REPORT GENERATOR — Fichtner-branded PPTX export
 * -------------------------------------------------------
 * Drop-in replacement for the existing $('downloadPpt') and
 * $('printPdf') handlers in app.js.
 *
 * INTEGRATION STEPS:
 * 1. Add this near the top of app.js, with the other imports:
 *      import { signals } from './data/signals.js';
 *
 * 2. Paste everything below the "=== PASTE INTO app.js ===" line
 *    in place of the existing:
 *      $('printPdf')?.addEventListener('click', () => window.print());
 *      $('downloadPpt')?.addEventListener('click', async () => { ... });
 *
 * Nothing else in app.js needs to change — this reuses the existing
 * allDevelopments(), allPipeline(), and eventData already in scope.
 */

const FICHTNER_BLUE = "005AAF";
const INK = "1B2733";
const SLATE = "5B6B79";
const LINE = "E4E9EE";
const LOGO_BASE64 = "data:image/png;base64,";

// Signals below this relevance score, or with an empty title/summary
// (the MASEN e-Tendering collector currently scrapes UI nav labels —
// e.g. "Outils informatiques" — as if they were tender signals; this
// filter keeps that noise out of anything shown to management),
// are excluded from the report.
const MIN_SIGNAL_RELEVANCE = 35;

function reportableSignals(allSignals) {
  return allSignals
    .filter(s => s.title && s.title.trim().length > 0 && (s.summary || '').trim().length >= 0 && s.relevanceScore >= MIN_SIGNAL_RELEVANCE)
    .sort((a, b) => (b.relevanceScore || 0) - (a.relevanceScore || 0))
    .slice(0, 6);
}

// === PASTE INTO app.js (replaces printPdf + downloadPpt handlers) ===

$('printPdf')?.addEventListener('click', () => {
  const devs = allDevelopments().slice(0, 5);
  const board = Object.entries(allPipeline());
  const topSignals = reportableSignals(signals);
  const type = $('reportType')?.value || 'Weekly Intelligence Brief';
  const period = $('reportPeriod')?.value.trim() || 'Current period';
  const classification = $('reportClassification')?.value || 'Internal — Fichtner';

  const win = window.open('', '_blank');
  win.document.write(`
    <html><head><title>${escapeHtml(type)}</title>
    <style>
      @page { size: A4 landscape; margin: 16mm; }
      body { font-family: Arial, Helvetica, sans-serif; color: ${INK}; }
      .logo { height: 26px; margin-bottom: 24px; }
      .eyebrow { color: ${FICHTNER_BLUE}; font-size: 11px; font-weight: bold; letter-spacing: 1px; text-transform: uppercase; }
      h1 { font-size: 26px; margin: 6px 0 20px; }
      .meta { color: ${SLATE}; font-size: 12px; margin-bottom: 24px; }
      section { margin-bottom: 28px; page-break-inside: avoid; }
      h2 { font-size: 15px; color: ${FICHTNER_BLUE}; border-bottom: 1px solid ${LINE}; padding-bottom: 6px; }
      .card { border: 1px solid ${LINE}; border-radius: 6px; padding: 12px 16px; margin-bottom: 10px; }
      .card h3 { font-size: 14px; margin: 4px 0; }
      .card p { font-size: 11px; color: ${SLATE}; margin: 0; }
      .badge { font-size: 9px; font-weight: bold; color: ${SLATE}; text-transform: uppercase; }
      footer { font-size: 9px; color: ${SLATE}; margin-top: 40px; }
    </style></head><body>
    <img class="logo" src="${LOGO_BASE64}" />
    <div class="eyebrow">Morocco Renewable Energy Intelligence</div>
    <h1>${escapeHtml(type)}</h1>
    <div class="meta">${escapeHtml(period)} &middot; ${escapeHtml(classification)}</div>

    <section><h2>01 &middot; Executive Summary</h2>
      ${devs.map(d => `<div class="card"><span class="badge">${escapeHtml(d.state || 'SIGNAL')} &middot; Score ${escapeHtml(d.score || '—')}</span><h3>${escapeHtml(d.title)}</h3><p>${escapeHtml(d.text)}${d.action ? ` &nbsp;→&nbsp; ${escapeHtml(d.action)}` : ''}</p></div>`).join('')}
    </section>

    <section><h2>02 &middot; Opportunity Pipeline</h2>
      ${board.map(([stage, items]) => `<div class="card"><span class="badge">${escapeHtml(stage)} &middot; ${items.length}</span>${items.map(i => `<h3>${escapeHtml(i.name || i.title)}</h3><p>${escapeHtml(i.note || i.text || '')} &middot; ${escapeHtml(i.owner || 'Unassigned')} &middot; Due ${escapeHtml(i.due || '—')}</p>`).join('')}</div>`).join('')}
    </section>

    <section><h2>03 &middot; Market Intelligence</h2>
      ${topSignals.map(s => `<div class="card"><span class="badge">${escapeHtml(s.fichtnerRelevance || 'WATCH')}</span><h3>${escapeHtml(s.title)}</h3><p>${escapeHtml(s.source || '')} &middot; ${escapeHtml((s.published || '').slice(0, 10))} &middot; Relevance ${escapeHtml(String(s.relevanceScore ?? '—'))}</p></div>`).join('') || '<p>No signals met the relevance threshold this period.</p>'}
    </section>

    <footer>Evidence-led intelligence. Analyst interpretation and Fichtner action are distinct from source-confirmed facts. &middot; Atlas Morocco Intelligence</footer>
    </body></html>
  `);
  win.document.close();
  win.focus();
  setTimeout(() => { win.print(); }, 300);
});

$('downloadPpt')?.addEventListener('click', async () => {
  const status = $('reportStatus');
  if (status) status.textContent = 'Generating PowerPoint…';
  try {
    const Pptx = window.PptxGenJS || window.pptxgen;
    if (typeof Pptx !== 'function') throw new Error('PowerPoint engine did not load.');

    const type = $('reportType')?.value || 'Weekly Intelligence Brief';
    const period = $('reportPeriod')?.value.trim() || 'Current period';
    const classification = $('reportClassification')?.value || 'Internal — Fichtner';
    const devs = allDevelopments().slice(0, 5);
    const board = Object.entries(allPipeline());
    const topSignals = reportableSignals(signals);

    const pptx = new Pptx();
    pptx.layout = 'LAYOUT_WIDE';
    pptx.author = 'Atlas';
    pptx.company = 'Fichtner';
    pptx.subject = 'Morocco Renewable Energy Intelligence';
    pptx.title = type;

    const PAGE_W = 13.333, PAGE_H = 7.5, M = 0.6;
    const addHeader = (s, eyebrow, title) => {
      s.addImage({ data: LOGO_BASE64, x: M, y: 0.35, w: 1.5, h: 0.255 });
      s.addText(eyebrow.toUpperCase(), { x: M, y: 0.85, w: 10, h: 0.3, fontSize: 11, bold: true, color: FICHTNER_BLUE, charSpacing: 1, fontFace: 'Arial' });
      s.addText(title, { x: M, y: 1.15, w: 11.5, h: 0.7, fontSize: 26, bold: true, color: INK, fontFace: 'Arial', margin: 0 });
    };
    const addFooter = (s) => {
      s.addText(`${classification}  ·  ${type}`, { x: M, y: PAGE_H - 0.42, w: 6, h: 0.3, fontSize: 9, color: SLATE, fontFace: 'Arial' });
      s.addText('Atlas Morocco Intelligence', { x: PAGE_W - M - 3.5, y: PAGE_H - 0.42, w: 3.5, h: 0.3, fontSize: 9, color: SLATE, align: 'right', fontFace: 'Arial' });
    };

    // Slide 1 — Cover
    {
      const s = pptx.addSlide();
      s.background = { color: 'FFFFFF' };
      s.addImage({ data: LOGO_BASE64, x: M, y: 0.55, w: 2.1, h: 0.357 });
      s.addText('MOROCCO RENEWABLE ENERGY INTELLIGENCE', { x: M, y: 2.9, w: 11, h: 0.4, fontSize: 14, bold: true, color: FICHTNER_BLUE, charSpacing: 1.5, fontFace: 'Arial' });
      s.addText(type, { x: M, y: 3.3, w: 11.5, h: 1.1, fontSize: 40, bold: true, color: INK, fontFace: 'Arial', margin: 0 });
      s.addText(`${period}  ·  ${classification}`, { x: M, y: 4.35, w: 10, h: 0.4, fontSize: 14, color: SLATE, fontFace: 'Arial' });
      s.addShape(pptx.ShapeType.rect, { x: M, y: 6.6, w: PAGE_W - M * 2, h: 0.02, fill: { color: LINE } });
      s.addText('Evidence-led intelligence. Analyst interpretation and Fichtner action are distinct from source-confirmed facts.', { x: M, y: 6.75, w: 11.5, h: 0.4, fontSize: 10, italic: true, color: SLATE, fontFace: 'Arial' });
    }

    // Slide 2 — Executive summary
    {
      const s = pptx.addSlide();
      s.background = { color: 'FFFFFF' };
      addHeader(s, '01 · Executive Summary', 'Signals that require a decision');
      let y = 2.15;
      devs.forEach(d => {
        const h = 1.45;
        s.addShape(pptx.ShapeType.roundRect, { x: M, y, w: PAGE_W - M * 2, h, rectRadius: 0.06, fill: { color: 'F7F9FB' }, line: { color: LINE, width: 0.75 } });
        const badgeColor = d.state === 'VERIFIED' ? '1E8E5A' : d.state === 'NEEDS REVIEW' ? 'C77700' : SLATE;
        s.addText(d.state || 'SIGNAL', { x: M + 0.25, y: y + 0.18, w: 3, h: 0.3, fontSize: 10, bold: true, color: badgeColor, fontFace: 'Arial' });
        s.addText(`Score ${d.score ?? '—'}`, { x: PAGE_W - M - 1.6, y: y + 0.18, w: 1.35, h: 0.3, fontSize: 10, bold: true, color: SLATE, align: 'right', fontFace: 'Arial' });
        s.addText(d.title, { x: M + 0.25, y: y + 0.42, w: PAGE_W - M * 2 - 0.5, h: 0.4, fontSize: 15, bold: true, color: INK, fontFace: 'Arial', margin: 0 });
        s.addText(`${d.text}${d.action ? `   →  ${d.action}` : ''}`, { x: M + 0.25, y: y + 0.88, w: PAGE_W - M * 2 - 0.5, h: 0.45, fontSize: 11, color: SLATE, fontFace: 'Arial', margin: 0 });
        y += h + 0.22;
      });
      addFooter(s);
    }

    // Slide 3 — Opportunity pipeline
    {
      const s = pptx.addSlide();
      s.background = { color: 'FFFFFF' };
      addHeader(s, '02 · Fichtner Action Pipeline', 'Opportunity pipeline');
      const colW = (PAGE_W - M * 2 - 0.4 * (board.length - 1)) / Math.max(1, board.length);
      let x = M;
      board.forEach(([stage, items]) => {
        s.addText(`${stage.toUpperCase()}  ·  ${items.length}`, { x, y: 2.15, w: colW, h: 0.35, fontSize: 12, bold: true, color: FICHTNER_BLUE, fontFace: 'Arial' });
        let cy = 2.6;
        items.forEach(it => {
          const h = 1.3;
          s.addShape(pptx.ShapeType.roundRect, { x, y: cy, w: colW, h, rectRadius: 0.06, fill: { color: 'F7F9FB' }, line: { color: LINE, width: 0.75 } });
          s.addText(it.name || it.title, { x: x + 0.18, y: cy + 0.15, w: colW - 0.36, h: 0.5, fontSize: 12, bold: true, color: INK, fontFace: 'Arial', margin: 0 });
          s.addText(it.note || it.text || '', { x: x + 0.18, y: cy + 0.62, w: colW - 0.36, h: 0.4, fontSize: 9.5, color: SLATE, fontFace: 'Arial', margin: 0 });
          s.addText(`${it.owner || 'Unassigned'}  ·  Due ${it.due || '—'}`, { x: x + 0.18, y: cy + 1.0, w: colW - 0.36, h: 0.25, fontSize: 9, color: SLATE, fontFace: 'Arial', margin: 0 });
          cy += h + 0.2;
        });
        x += colW + 0.4;
      });
      addFooter(s);
    }

    // Slide 4 — Market signals (real, filtered)
    {
      const s = pptx.addSlide();
      s.background = { color: 'FFFFFF' };
      addHeader(s, '03 · Market Intelligence', 'Signals worth reading this week');
      let y = 2.15;
      if (!topSignals.length) {
        s.addText('No signals met the relevance threshold this period.', { x: M, y, w: 11, h: 0.4, fontSize: 13, color: SLATE, fontFace: 'Arial' });
      }
      topSignals.forEach(sig => {
        const h = 0.85;
        s.addText(sig.fichtnerRelevance || 'WATCH', { x: M, y, w: 1.3, h: 0.3, fontSize: 9, bold: true, color: FICHTNER_BLUE, fontFace: 'Arial' });
        s.addText(sig.title, { x: M + 1.4, y, w: PAGE_W - M * 2 - 1.4, h: 0.4, fontSize: 13, bold: true, color: INK, fontFace: 'Arial', margin: 0 });
        s.addText(`${sig.source || ''}  ·  ${(sig.published || '').slice(0, 10)}  ·  Relevance ${sig.relevanceScore ?? '—'}`, { x: M + 1.4, y: y + 0.38, w: PAGE_W - M * 2 - 1.4, h: 0.3, fontSize: 9.5, color: SLATE, fontFace: 'Arial', margin: 0 });
        s.addShape(pptx.ShapeType.rect, { x: M, y: y + h - 0.05, w: PAGE_W - M * 2, h: 0.01, fill: { color: LINE } });
        y += h;
      });
      addFooter(s);
    }

    // Slide 5 — Source note
    {
      const s = pptx.addSlide();
      s.background = { color: 'FFFFFF' };
      addHeader(s, '04 · Methodology', 'Source note');
      const notes = [
        'This brief is generated from Atlas — Fichtner\'s continuous Morocco renewable-energy monitoring workspace.',
        'Developments are tagged Verified, Needs Review, or Watch based on source type and corroboration.',
        `Market signals below relevance threshold ${MIN_SIGNAL_RELEVANCE}, or lacking a title, are excluded from this brief.`,
        'Analyst interpretation and recommended Fichtner action are distinct from source-confirmed facts.',
      ];
      let y = 2.3;
      notes.forEach(n => {
        s.addText([{ text: n, options: { bullet: { code: '2022' }, breakLine: true } }], { x: M, y, w: 11.5, h: 0.5, fontSize: 13, color: INK, fontFace: 'Arial', paraSpaceAfter: 10 });
        y += 0.55;
      });
      addFooter(s);
    }

    await pptx.writeFile({ fileName: `Atlas_Morocco_Renewable_Intelligence_Brief.pptx` });
    if (status) status.textContent = 'PowerPoint downloaded successfully.';
  } catch (err) {
    console.error(err);
    if (status) status.textContent = 'PowerPoint generation failed: ' + err.message;
  }
});
